import{_ as t,o,c as a,ag as s}from"./chunks/framework.44aEvdQQ.js";const m=JSON.parse(`{"title":"When Done Means Done","description":"A confirmation that nothing happened behind it is worse than no confirmation at all. We fixed the moment where trust breaks.","frontmatter":{"title":"When Done Means Done","date":"2026-03-25","series":"AI Behaviour","description":"A confirmation that nothing happened behind it is worse than no confirmation at all. We fixed the moment where trust breaks.","prev":false,"next":false},"headers":[],"relativePath":"blog/20-when-done-means-done.md","filePath":"blog/20-when-done-means-done.md","blogPosts":[{"url":"/blog/21-not-everyone-works-forty-hours","fm":{"title":"Not Everyone Works Forty Hours","date":"2026-03-29","series":"Features","description":"Capacity planning only works if the system knows how each person actually works. VERA was treating your contractors like full-time employees. It no longer does."}},{"url":"/blog/20-when-done-means-done","fm":{"title":"When Done Means Done","date":"2026-03-25","series":"AI Behaviour","description":"A confirmation that nothing happened behind it is worse than no confirmation at all. We fixed the moment where trust breaks."}},{"url":"/blog/19-the-briefing","fm":{"title":"The Briefing That Replaced the Monday Check-in","date":"2026-03-24","series":"Features","description":"The morning summary now answers two questions simultaneously: what am I supposed to be working on, and where do my projects stand?"}},{"url":"/blog/18-sheets-formulas-as-code","fm":{"title":"Building the Dashboard the Owner Actually Needs","date":"2026-03-15","series":"Data Model","description":"A live dashboard that answers the real questions: which projects are healthy, which are at risk, and what the business earned this month."}},{"url":"/blog/17-two-spreadsheets","fm":{"title":"The Dashboard Is Always Current","date":"2026-03-13","series":"Architecture","description":"The client''s reporting view and the database are separate spreadsheets. The client can never accidentally break the data — and they never have to request a report."}},{"url":"/blog/16-column-order-is-the-api","fm":{"title":"The Invisible Contract in the Spreadsheet","date":"2026-03-12","series":"Data Model","description":"Google Sheets doesn''t enforce its own structure. We had to. The rules we built to keep the data trustworthy."}},{"url":"/blog/14-agile-as-billing-model","fm":{"title":"Agile as a Billing Model","date":"2026-03-08","series":"Business Logic","description":"A sprint is a delivery unit and a revenue recognition unit. Timeliness of logging determines timeliness of revenue — they''re the same thing."}},{"url":"/blog/15-ooo-is-a-financial-event","fm":{"title":"Absence Is Data Too","date":"2026-03-08","series":"Business Logic","description":"Time off is a cost. If it doesn''t appear in the same system as time worked, the capacity picture is wrong and the P&L is incomplete."}},{"url":"/blog/13-design-md-rethink","fm":{"title":"Writing It Down Made Us Confront What We''d Built","date":"2026-03-07","series":"Architecture","description":"Six weeks in, we stopped and wrote down every decision we''d made. Several of them turned out to be wrong."}},{"url":"/blog/12-phased-expansion","fm":{"title":"What Becomes Possible When the Data Is Real","date":"2026-03-03","series":"Features","description":"Once time tracking is accurate and timely, a layer of project intelligence that was previously impossible becomes straightforward."}},{"url":"/blog/11-multi-tenancy-bugs","fm":{"title":"Reliability Is the Promise","date":"2026-03-01","series":"Architecture","description":"Timeliness only works if the system is there when the moment arrives. Getting multi-tenant reliability right was non-negotiable."}},{"url":"/blog/10-multi-tenancy","fm":{"title":"Each Client Gets Their Own VERA","date":"2026-02-25","series":"Architecture","description":"Multi-tenancy wasn''t a feature request. It was the point. A tool that feels shared feels like someone else''s."}},{"url":"/blog/09-timebot-becomes-vera","fm":{"title":"TimeBot Becomes VERA","date":"2026-02-22","series":"Origins","description":"A name signals a relationship. We weren''t building a utility."}},{"url":"/blog/07-retainers-are-weird","fm":{"title":"Retainers Without Timely Data Are Just Guesses","date":"2026-02-19","series":"Business Logic","description":"A retainer is a commitment to deliver a volume of work within a period. If you don''t know where you are until the invoice, you''ve already lost."}},{"url":"/blog/08-snapshots-version-control-spreadsheet","fm":{"title":"The Business Was There Last Tuesday Too","date":"2026-02-19","series":"Infrastructure","description":"When data is live and timely, the next question is whether you can go back. We built that in from the start."}},{"url":"/blog/06-roles-and-dollars","fm":{"title":"The Data Is Only Worth Protecting If It''s Worth Something","date":"2026-02-17","series":"Permissions","description":"When the data is timely and accurate, the financial numbers become real. Real numbers need to reach the right people — and not the wrong ones."}},{"url":"/blog/04-schema-grows-up","fm":{"title":"Making a Slack Message Do the Work of a Form","date":"2026-02-12","series":"Data Model","description":"We removed the interface. That meant every piece of information the owner needed had to be captured from a casual Slack message without making that message any harder to send."}},{"url":"/blog/05-prompt-engineering-wars","fm":{"title":"The Clarifying Questions Problem","date":"2026-02-12","series":"AI Behaviour","description":"Timeliness is the whole product. Any friction that risks the timing is a product failure."}},{"url":"/blog/03-socket-mode-railway","fm":{"title":"The Deployment That Didn''t Require a Web App","date":"2026-02-11","series":"Infrastructure","description":"We needed to deploy without adding anything to the client''s stack. Socket Mode and Railway made that possible for almost nothing."}},{"url":"/blog/01-the-problem","fm":{"title":"The Problem That Made VERA Necessary","date":"2026-02-10","series":"Origins","description":"Every time tracking tool ever built starts from the wrong assumption. We found the one thing that fixes it."}},{"url":"/blog/02-day-one-slack-claude-sheets","fm":{"title":"Day One: Slack → Claude → Google Sheets","date":"2026-02-10","series":"Origins","description":"The three components we chose on day one — and why each one was chosen specifically because it required no new interface."}}]}`),i={name:"blog/20-when-done-means-done.md"};function n(r,e,h,l,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s("<p>There is a specific kind of failure that destroys trust faster than any other. The system tells you it is done. You move on to the next thing. And later you discover that nothing actually happened. The project was never created. The allocation was never made. The hours were never logged. The system lied, and you only found out because you happened to check.</p><p>This is worse than an error message. An error message tells you something went wrong. You can fix it. You can try again. A false confirmation tells you everything is fine when it is not. You lose the moment. You lose the context. And by the time you realise, the damage is compounding — decisions have been made on data that does not exist.</p><p>We found this happening in VERA. A project manager would say &quot;create a project called Nightshade for Adidas.&quot; VERA would ask for the details. The PM would say &quot;Fixed price, 100 hours, $100 an hour.&quot; VERA would ask for confirmation. The PM would type &quot;1.&quot; And VERA would say done. But nothing had been written. No row in the sheet. No audit trail. No notification to the team. The PM walked away thinking the project existed. It did not.</p><p>The root cause was subtle. When a user sends a bare confirmation — &quot;1&quot;, &quot;yes&quot;, &quot;go ahead&quot; — the system was routing it to a smaller, faster language model. That model saw the conversation history, saw that a project creation had been discussed, and concluded that the work must have already been done. It generated a response saying &quot;done&quot; without ever calling the tool that actually creates the project. It hallucinated the action.</p><p>The fix had two parts. First, we forced confirmation inputs to use the more capable model and made it mandatory that the response include a tool call. The API itself now rejects a text-only response on a confirmation turn. If Claude cannot figure out which tool to call, it has to say so — it cannot fake success.</p><p>Second, we changed what &quot;done&quot; looks like. Before, a completed action looked the same as every other message — a paragraph of prose with the word &quot;done&quot; somewhere in it. Now it looks like a receipt. A checkmark, a label, and a one-line summary of exactly what changed. You can tell at a glance — without reading a word — that something was written. The visual pattern is distinct from a question, a clarification, or an error. It is unmistakable.</p><p>This matters because timeliness is the product. The entire value of VERA is that the data exists the moment the work happens. A false confirmation breaks that promise silently. The PM thinks the project is set up. The team member thinks their allocation is in place. The owner thinks the numbers are current. None of it is true, and nobody knows until something else fails downstream.</p><p>The same session uncovered a related problem with allocations. When a PM said &quot;give Sarah 10 hours on Development for Project Nightshade,&quot; the system was looking at Sarah&#39;s existing allocations on that project and substituting the task type from an earlier allocation. Sarah would get a message saying she had been allocated 10 hours of Strategy when the PM had explicitly said Development. The system was being too clever — inferring when it should have been listening.</p><p>We fixed that by drawing a hard line. Task inference — where the system looks at existing allocations to figure out what kind of work you are doing — only applies when you are logging time. When a manager is allocating hours, the task type comes from what the manager said. Period. The system passes the name directly and the server resolves it. No inference, no substitution, no cleverness.</p><p>These are not the kind of bugs that show up in a feature list or a demo. They show up three weeks into real usage, when someone trusts the system enough to stop double-checking. That is exactly when a false confirmation does the most damage. The fix is not just technical. It is a commitment: when VERA says done, the work is done. When it shows a receipt, the data is in the sheet. When a manager allocates Development hours, Development is what gets recorded.</p><p>Trust is not a feature you ship. It is the accumulation of every moment where the system did exactly what it said it did.</p>",11)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
